    const run = synthesize || async function(input) {
      const result = await new OpenAI3({ apiKey: process.env.OPENAI_API_KEY, timeout: 25e3, maxRetries: 0 }).audio.speech.create({ model: "gpt-4o-mini-tts", voice: "coral", input, instructions: MARKETING_VOICE_INSTRUCTIONS, response_format: "mp3" });
      return Buffer.from(await result.arrayBuffer());
    };
    const audio = await run(text2);
    if (!audio.length || audio.length > 65e4) throw new Error("Invalid voice output");
    await job.set({ status: "done", completedAt: Date.now(), bytes: audio.length }, { merge: true });
